import React, { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

const StudentHome = () => {
  const navigate = useNavigate();
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const menuRef = useRef(null);

  // Закрываем меню при клике вне его области
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (menuRef.current && !menuRef.current.contains(event.target)) {
        setIsMenuOpen(false);
      }
    };

    if (isMenuOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [isMenuOpen]);

  const handleLogout = () => {
    // TODO: Здесь будет логика выхода (очистка токена, redirect на '/')
    console.log('Выход из аккаунта');
    navigate('/');
  };

  return (
    <div className="min-h-screen w-full bg-secondary flex flex-col">
      {/* Шапка */}
      <header className="relative flex items-center justify-between px-5 py-4 bg-primary shadow-sm">
        {/* Логотип или название */}
        <div className="flex items-center gap-3">
          <div className="flex h-10 w-10 items-center justify-center rounded-full bg-black text-primary font-bold text-lg">
            Т
          </div>
          <span className="text-xl font-semibold text-black">Талон</span>
        </div>

        {/* Кнопка меню "..." */}
        <div className="relative" ref={menuRef}>
          <button
            type="button"
            onClick={() => setIsMenuOpen(!isMenuOpen)}
            aria-label="Открыть меню"
            aria-expanded={isMenuOpen}
            className="flex h-10 w-10 items-center justify-center rounded-full text-gray transition-colors hover:bg-gray/10 hover:text-black"
          >
            <svg width="24" height="24" viewBox="0 0 24 24" fill="currentColor">
              <circle cx="12" cy="5" r="2" />
              <circle cx="12" cy="12" r="2" />
              <circle cx="12" cy="19" r="2" />
            </svg>
          </button>

          {/* Выпадающий список */}
          {isMenuOpen && (
            <div className="absolute right-0 top-12 z-50 w-56 rounded-xl bg-primary p-2 shadow-xl border border-gray/10 animate-in fade-in slide-in-from-top-2 duration-200">
              <button
                type="button"
                onClick={handleLogout}
                className="flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left text-sm text-[#F24444] transition-colors hover:bg-[rgba(242,68,68,0.08)]"
              >
                <svg
                  width="20"
                  height="20"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  aria-hidden
                >
                  <path d="M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4 M10 17l5-5-5-5 M15 12H3" />
                </svg>
                <span className="font-medium">Выйти из аккаунта</span>
              </button>
            </div>
          )}
        </div>
      </header>

      {/* Основной контент страницы студента */}
      <main className="flex-1 px-5 py-8">
        <div className="mx-auto max-w-[480px]">
          <h1 className="text-3xl font-semibold text-black">Добро пожаловать!</h1>
          <p className="mt-2 text-sm text-gray">
            Здесь будет основной интерфейс студента (QR-код, история питаний и т.д.)
          </p>
          
          {/* Заглушка для будущего контента */}
          <div className="mt-8 flex h-64 items-center justify-center rounded-2xl border-2 border-dashed border-gray/30 bg-primary">
            <p className="text-sm text-gray">Контент страницы студента</p>
          </div>
        </div>
      </main>
    </div>
  );
};

export default StudentHome;
